/**
 * Every CID-10 category, in ascending order, with the fourth characters of its subcategories:
 * `A00: "019"` stands for `A00.0`, `A00.1` and `A00.9`, and an empty string for a category
 * that is not subdivided, once `readCid10Subcategories` has unpacked it. It holds the codes of `CID10_DESCRIPTIONS` without the descriptions,
 * in the same order, so that checking a code does not cost the whole table. The `U07` codes come
 * from the SIM table, as in `cid10-descriptions.ts`.
 *
 * Packed by `packCid10Categories` (scripts/cid10.ts), which `readCid10Subcategories` reads.
 *
 * Generated by `node ./scripts/cid10.ts`. Do not edit by hand.
 *
 * @see Official: http://www2.datasus.gov.br/cid10/V2008/downloads/CID10CSV.zip
 * The CID-10 tables in CSV, as published by DATASUS (Ministério da Saúde).
 * @see Official: http://www2.datasus.gov.br/cid10/V2008/descrcsv.htm
 * The DATASUS page that links the archive and documents its files, columns and encoding.
 * @see Official: ftp://ftp.datasus.gov.br/dissemin/publicos/SIM/CID10/TABELAS/CID10.DBF
 * The CID-10 table of the SIM, source of the `U07` codes.
 */
export const CID10_SUBCATEGORIES =
	"";
